package de.sebaro_ventures.design.designsystem

import androidx.compose.runtime.Immutable
import androidx.compose.runtime.getValue
import androidx.compose.ui.input.key.key
import org.json.JSONArray
import org.json.JSONObject

/** FACTS-CONTRACT §8.1: the state of a fact or note. */
enum class SbFactState(val id: String) {
    Shown("shown"),
    UnverifiedDisclosure("unverified-disclosure"),
    Hidden("hidden"),
    Stale("stale");

    companion object {
        fun fromId(id: String): SbFactState =
            entries.firstOrNull { it.id == id } ?: throw IllegalArgumentException("unknown fact state '$id'")
    }
}

/** The four check states (D15, FACTS-CONTRACT §6.3) in contract order, worst last. */
enum class SbCheckResult(val id: String) {
    Passed("passed"),
    Open("open"),
    Skipped("skipped"),
    Failed("failed");

    companion object {
        fun fromId(id: String): SbCheckResult =
            entries.firstOrNull { it.id == id } ?: throw IllegalArgumentException("unknown check state '$id'")
    }
}

/** One note of `check_facts.py --notes` (FACTS-CONTRACT §8.6), texts in the display language. */
@Immutable
data class SbNote(
    val n: Int?,
    val refs: List<String>,
    val state: SbFactState,
    val disclosure: Boolean,
    val result: SbCheckResult,
    val stateWord: String,
    val checkedOn: String?,
    val forVersion: String?,
    val by: String?,
    val method: List<String>,
    val proofNotes: List<String>,
    val reasons: List<String>,
    val disclosures: List<String>,
    val limits: List<String>,
    val notVerified: String?,
    val checks: List<String>,
) {
    /** D21: a reassuring claim only when shown; an outflow also when unverified. */
    val showsClaim: Boolean
        get() = state == SbFactState.Shown || (disclosure && state == SbFactState.UnverifiedDisclosure)

    /** „bestanden · geprüft am 10.10.2026 für 1.4.0“; „nicht belegt · …“ when not shown (10 §3.3). */
    fun shortLine(withVersion: Boolean = true): String {
        val line = when (result) {
            SbCheckResult.Open, SbCheckResult.Skipped -> checkedOn ?: stateWord
            else -> {
                val date = listOfNotNull(checkedOn, forVersion?.takeIf { withVersion }).joinToString(" ")
                if (date.isEmpty()) stateWord else "$stateWord · $date"
            }
        }
        return if (state == SbFactState.Shown) line else listOfNotNull(notVerified, line).joinToString(" · ")
    }

    /** Lines 2–5 of the note (method, proof notes, reasons, outflows, limits); sender and link follow. */
    fun bodyLines(): List<String> = method + proofNotes + reasons + disclosures + limits
}

/** One check of the list „Wie geprüft?“ in execution order. */
@Immutable
data class SbCheck(
    val id: String,
    val result: SbCheckResult,
    val stateWord: String,
    val title: String,
    val date: String?,
    val by: String?,
    val reason: String?,
    val limit: String?,
    val evidence: List<String>,
)

/** All note data of one product. */
@Immutable
data class SbNotes(
    val productName: String,
    val productVersion: String,
    val demo: String?,
    val stale: Boolean,
    val staleNotice: String?,
    val nextDue: String?,
    val nextDueDate: String?,
    val network: String,
    val checks: List<SbCheck>,
    val claims: List<SbNote>,
    val numbered: List<SbNote>,
) {
    /** The note of exactly these fact refs (`accounts`, `tracking.adIds`, `paths.csv-export` …), or null. */
    fun note(vararg refs: String): SbNote? = claims.firstOrNull { it.refs == refs.toList() }

    /** R2 (FACTS-CONTRACT §8.3) at run time: with a live path to a remote place, stale after nextDue. */
    fun isStale(todayIso: String): Boolean =
        stale || (network != "none" && nextDueDate != null && todayIso > nextDueDate)

    fun count(result: SbCheckResult): Int = checks.count { it.result == result }
}

/** Reads the JSON of `python3 tools/check_facts.py facts.json --notes [--note …]`; [lang] "de" or "en". */
object SbNotesJson {
    fun parse(json: String, lang: String = "de"): SbNotes {
        val root = JSONObject(json)
        val product = root.getJSONObject("product")
        val notes = root.getJSONObject("notes")
        val labels = notes.getJSONObject("labels")
        return SbNotes(
            productName = product.getString("name"),
            productVersion = product.getString("version"),
            demo = labels.optJSONObject("demo").text(lang),
            stale = notes.getBoolean("stale"),
            staleNotice = labels.optJSONObject("stale").text(lang),
            nextDue = labels.optJSONObject("nextDue").text(lang),
            nextDueDate = notes.getJSONObject("freshness").str("nextDue"),
            network = root.optJSONObject("view")?.str("network") ?: "automatic",
            checks = notes.getJSONArray("checks").objects().map { check(it, lang) },
            claims = notes.getJSONArray("claims").objects().map { note(it, lang) },
            numbered = notes.optJSONArray("numbered")?.objects()?.map { note(it, lang) } ?: emptyList(),
        )
    }

    private fun note(o: JSONObject, lang: String): SbNote {
        val l = o.getJSONObject("labels")
        return SbNote(
            n = if (o.isNull("n")) null else o.getInt("n"),
            refs = o.getJSONArray("refs").strings(),
            state = SbFactState.fromId(o.getString("state")),
            disclosure = o.optBoolean("disclosure"),
            result = SbCheckResult.fromId(o.getString("result")),
            stateWord = l.optJSONObject("state").text(lang) ?: o.getString("result"),
            checkedOn = l.optJSONObject("checkedOn").text(lang),
            forVersion = l.optJSONObject("forVersion").text(lang),
            by = l.optJSONObject("by").text(lang),
            method = o.optJSONArray("method").texts(lang),
            proofNotes = o.optJSONArray("proofNotes").texts(lang),
            reasons = o.optJSONArray("reasons")?.objects()?.mapNotNull { it.optJSONObject("text").text(lang) }
                ?: emptyList(),
            disclosures = o.optJSONArray("disclosures")?.objects()?.mapNotNull { outflowLine(it, lang) }
                ?: emptyList(),
            limits = l.optJSONArray("limits").texts(lang),
            notVerified = l.optJSONObject("notVerified").text(lang),
            checks = o.optJSONArray("checks")?.strings() ?: emptyList(),
        )
    }

    private fun check(o: JSONObject, lang: String): SbCheck {
        val l = o.getJSONObject("labels")
        return SbCheck(
            id = o.getString("id"),
            result = SbCheckResult.fromId(o.getString("state")),
            stateWord = l.optJSONObject("state").text(lang) ?: o.getString("state"),
            title = o.optJSONObject("title").text(lang) ?: o.getString("id"),
            date = l.optJSONObject("date").text(lang),
            by = l.optJSONObject("by").text(lang),
            reason = o.optJSONObject("reason").text(lang),
            limit = l.optJSONObject("limit").text(lang),
            evidence = o.optJSONArray("evidence")?.objects()?.mapNotNull { it.str("ref") } ?: emptyList(),
        )
    }

    /** „<data> an <to>: <trigger>, <transport>, <retention> (<note>)“ (10 §3.3 item 4). */
    private fun outflowLine(d: JSONObject, lang: String): String? {
        val l = d.optJSONObject("labels") ?: return null
        val head = listOfNotNull(l.optJSONObject("data").text(lang), l.optJSONObject("to").text(lang))
            .joinToString(if (lang == "de") " an " else " to ")
        val retention = l.optJSONObject("retention").text(lang)?.let { r ->
            l.optJSONObject("retentionNote").text(lang)?.let { "$r ($it)" } ?: r
        }
        val tail = listOfNotNull(
            l.optJSONObject("trigger").text(lang),
            l.optJSONObject("transport").text(lang),
            retention,
            l.optJSONObject("notVerified").text(lang),
        ).joinToString(", ")
        return listOf(head, tail).filter { it.isNotEmpty() }.joinToString(": ").ifEmpty { null }
    }
}

private fun JSONObject?.text(lang: String): String? {
    if (this == null) return null
    return str(lang) ?: str("de")
}

private fun JSONObject.str(key: String): String? = if (isNull(key)) null else optString(key).ifEmpty { null }

private fun JSONArray.objects(): List<JSONObject> = (0 until length()).map { getJSONObject(it) }

private fun JSONArray.strings(): List<String> = (0 until length()).map { getString(it) }

private fun JSONArray?.texts(lang: String): List<String> = this?.objects()?.mapNotNull { it.text(lang) } ?: emptyList()

// Per-action hints come from facts.json: the notes carry no labels for local paths.

/** FACTS-CONTRACT §6.2 trigger labels (contract defaults). */
private val TRIGGER_DE = mapOf("automatic" to "automatisch", "on-user-command" to "nur auf deinen Befehl", "never" to "nie")
private val TRIGGER_EN = mapOf("automatic" to "automatically", "on-user-command" to "only when you ask", "never" to "never")

/** Per-action hints (10 §3.4), keyed by the action label of each path: „Nur auf deinen Befehl. Ziel: …“. */
object SbActionHints {
    fun parse(factsJson: String, lang: String = "de"): Map<String, String> {
        val facts = JSONObject(factsJson)
        val places = facts.getJSONArray("places").objects().associateBy { it.getString("id") }
        val out = LinkedHashMap<String, String>()
        facts.getJSONArray("paths").objects().forEach { path ->
            val action = label(path.opt("action"), lang) ?: return@forEach
            val trigger = (if (lang == "de") TRIGGER_DE else TRIGGER_EN)[path.getString("trigger")] ?: return@forEach
            val to = places[path.getString("to")]?.let { placeLabel(it, lang) } ?: return@forEach
            val head = trigger.replaceFirstChar { it.uppercase() }
            out[action] = if (lang == "de") "$head. Ziel: $to." else "$head. Destination: $to."
        }
        return out
    }

    /**
     * Display form (FACTS-CONTRACT 1.2 §5.5): „label · City (CC)“, without a city „label · (CC)“ or, for a place named
     * by its jurisdiction (D90), „label · Rechtsraum EU“; „label · Ort nicht belegt“ when unverified.
     */
    private fun placeLabel(place: JSONObject, lang: String): String? {
        val label = label(place.opt("label"), lang) ?: return null
        val kind = place.getString("kind")
        if (kind == "device" || kind == "user-destination") return label
        val verified = place.optJSONObject("proof")?.optString("status") == "verified"
        if (!verified) return if (lang == "de") "$label · Ort nicht belegt" else "$label · location not verified"
        val city = place.str("city")
        val country = place.str("country")
        val jurisdiction = place.str("jurisdiction")
        return when {
            city != null && country != null -> "$label · $city ($country)"
            country != null -> "$label · ($country)"
            jurisdiction != null -> "$label · " + jurisdictionLabel(jurisdiction, lang)
            else -> label
        }
    }

    /** FACTS-CONTRACT 1.2 §5.5 jurisdiction words (the same as `check_facts.py`). */
    private fun jurisdictionLabel(code: String, lang: String): String = when (code) {
        "EU" -> if (lang == "de") "Rechtsraum EU" else "EU jurisdiction"
        "EEA" -> if (lang == "de") "Rechtsraum EWR" else "EEA jurisdiction"
        else -> code
    }

    private fun label(value: Any?, lang: String): String? = when (value) {
        is String -> value
        is JSONObject -> value.text(lang)
        else -> null
    }
}
